<?php
namespace CmuLms;
final class Submission extends Model {public static function forTask(int $task):array{return self::all('SELECT s.*,u.name,u.id_number FROM task_submissions s JOIN users u ON u.id=s.student_id WHERE s.task_id=? ORDER BY s.submitted_at DESC',[$task]);}public static function forCourse(int $course):array{return self::all('SELECT s.*,u.name,u.id_number,t.title task_title,t.course_id FROM task_submissions s JOIN users u ON u.id=s.student_id JOIN tasks t ON t.id=s.task_id WHERE t.course_id=? ORDER BY s.submitted_at DESC',[$course]);}public static function byStudent(int $student):array{return self::all('SELECT s.*,t.title task_title,c.code FROM task_submissions s JOIN tasks t ON t.id=s.task_id JOIN courses c ON c.id=t.course_id WHERE s.student_id=? ORDER BY s.submitted_at DESC',[$student]);}}
